const examples={river:{sentence:"They walked along the bank of the river.",meaning:"河岸",explanation:"这里指河流两侧的岸地。",before:"They walked along the ",after:" of the river."},loan:{sentence:"The bank approved her loan yesterday.",meaning:"银行",explanation:"这里指提供贷款的金融机构。",before:"The ",after:" approved her loan yesterday."}};
for(const button of document.querySelectorAll('[data-example]'))button.addEventListener('click',()=>{const example=examples[button.dataset.example];const passage=document.querySelector('#passage');passage.replaceChildren(document.createTextNode(example.before));const mark=document.createElement('mark');mark.textContent='bank';passage.append(mark,document.createTextNode(example.after));document.querySelector('#meaning').textContent=example.meaning;document.querySelector('#explanation').textContent=example.explanation;document.querySelector('#original').textContent=example.sentence;for(const b of document.querySelectorAll('[data-example]'))b.setAttribute('aria-pressed',String(b===button));});
